const normalize = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
const tokenize = value => normalize(value).split(/[^a-z0-9]+/).filter(part => part.length > 3)
const intentHints = [
  [/polleria|restaurante|comida|hamburguesa|delivery|cafeteria|menu/, ['hero-section','product-card','product-gallery','cart-drawer','sticky-add-to-cart','trust-badges','checkout-steps','bottom-navigation']],
  [/tienda|ecommerce|compras|productos|catalogo/, ['product-card','faceted-filters','product-detail-page','cart-drawer','product-gallery','checkout-steps']],
  [/futurista|moderno|tecnologia|premium|elegante|sofisticado/, ['bento-grid','glassmorphism','mesh-gradient','microinteractions','typographic-hero','premium-dark']],
  [/academia|universidad|estudiante|cursos|educacion/, ['education-course-progress-tracker','education-timetable-grid','education-grade-breakdown','tabs','calendar-view']],
  [/panel|dashboard|finanzas|analitica|metricas|estadisticas/, ['stat-cards','data-table','dashboard-analytics-chart-drilldown','line-chart','data-visualization-heatmap']],
  [/agencia|portafolio|freelancer|profesional/, ['bento-grid','typographic-hero','testimonial-card','card-grid','editorial-style']],
  [/app|aplicacion|movil|celular/, ['bottom-navigation','bottom-sheet','onboarding','mobile-drawer','segmented-control']],
  [/mejorar|redisen|redise|usabilidad|ux|interfaz/, ['bento-grid','sticky-navbar','accordion','toast','skeleton-loading','feedback-accessible-error-navigation']]
]
const map = new Map(knowledge.map(item => [item.id, item]))

export function getPatterns(ids = []) {
  return [...new Set(ids)].filter(id=>typeof id === 'string').map(id => map.get(id)).filter(Boolean).slice(0, 20)
}
export function searchPatterns(query, selectedIds = [], limit = 10) {
  const tokens = tokenize(query).slice(0, 28)
  const normalized = normalize(query)
  const hints = intentHints.filter(([regex]) => regex.test(normalized)).flatMap(([,ids])=>ids)
  const hintSet = new Set(hints)
  const selectedSet = new Set(selectedIds)
  const ranked = knowledge.map(item => {
    const name = normalize(item.name)
    const description = normalize(item.description + ' ' + item.useCase)
    let score = (selectedSet.has(item.id) ? 250 : 0) + (hintSet.has(item.id) ? 80 : 0)
    for (const token of tokens) {
      if (name.includes(token)) score += 14
      else if (description.includes(token)) score += 3
    }
    return {item,score}
  }).filter(result=>result.score>0).sort((a,b)=>b.score-a.score)
  const result = ranked.map(entry=>entry.item).slice(0, Math.min(16,Math.max(1,limit)))
  if (result.length >= 4) return result
  const used = new Set(result.map(x=>x.id))
  for(const id of ['hero-section','bento-grid','product-card','sticky-navbar','bottom-navigation','accordion','mobile-drawer']){
    if(result.length >= Math.min(16,Math.max(1,limit)))break
    if(!used.has(id) && map.has(id)) {result.push(map.get(id));used.add(id)}
  }
  return result
}
